package com.estoqueinteligente.report;
import com.estoqueinteligente.product.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class WhatsappMessageService{private final ProductService products;public WhatsappMessageService(ProductService p){products=p;}public List<WhatsappMessageResponse> getMessages(){List<WhatsappMessageResponse> out=new ArrayList<>();for(ProductResponse p:products.findAll()){if(p.getStatus()==ProductStatus.PENDENTE_CONTAGEM)out.add(new WhatsappMessageResponse(p.getId(),p.getName(),"Item pendente de contagem: "+p.getName()+". Favor realizar a conferência do almoxarifado.","Conferência pendente"));if(p.getBalance()<0)out.add(new WhatsappMessageResponse(p.getId(),p.getName(),"Lista de reposição: "+p.getName()+" precisa de "+Math.abs(p.getBalance())+" "+(p.getUnitOfMeasure()==null?"unidade(s)":p.getUnitOfMeasure())+".","Necessidade de reposição"));}return out;}}
